/* Shared canvas chrome uses the original control nodes and handlers. */
const CanvasUI={enhance(){for(const toolbar of document.querySelectorAll('.camera-tools,.world-camera')){if(toolbar.querySelector('.camera-secondary'))continue;const secondary=[...toolbar.children].filter(el=>['resetBoard','focusSelected','lastPinned','worldReset','worldFocus'].includes(el.id)||el.classList.contains('board-zoom-details'));if(!secondary.length)continue;const menu=document.createElement('details');menu.className='camera-secondary';menu.innerHTML='<summary>More</summary><div></div>';secondary.forEach(el=>menu.lastElementChild.append(el));toolbar.append(menu)}},};
new MutationObserver(()=>CanvasUI.enhance()).observe(document.querySelector('#workspacePanels'),{childList:true,subtree:true});CanvasUI.enhance();
